const char* relationships="<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">";
std::string content_type(const std::string& overrides){return "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/>"+overrides+"</Types>";}
std::string cell_ref(std::uint32_t row,std::uint32_t col){std::string c;for(++col;col;col=(col-1)/26)c.insert(c.begin(),char('A'+(col-1)%26));return c+std::to_string(row+1);}
