void export_docx(const Document& document,const std::filesystem::path& path){
  if(document.source_format=="docx"&&!document.original_package.empty()){fs::write_bytes_atomic(path,document.original_package);return;}
  auto run_xml=[](const Run& run){std::ostringstream out;const auto color=[](const Color& c){const char* digits="0123456789ABCDEF";std::string value(6,'0');value[0]=digits[c.red>>4];value[1]=digits[c.red&15];value[2]=digits[c.green>>4];value[3]=digits[c.green&15];value[4]=digits[c.blue>>4];value[5]=digits[c.blue&15];return value;};out<<"<w:r><w:rPr><w:rFonts w:ascii=\""<<strings::xml_escape(run.style.font_family)<<"\" w:hAnsi=\""<<strings::xml_escape(run.style.font_family)<<"\"/>"<<(run.style.font_weight>=600?"<w:b/>":"")<<(run.style.italic?"<w:i/>":"")<<(run.style.underline?"<w:u w:val=\"single\"/>":"")<<(run.style.strike?"<w:strike/>":"")<<"<w:color w:val=\""<<color(run.style.foreground)<<"\"/><w:sz w:val=\""<<static_cast<int>(run.style.font_size_points*2)<<"\"/></w:rPr><w:t xml:space=\"preserve\">"<<strings::xml_escape(run.text)<<"</w:t></w:r>";return out.str();};
  std::ostringstream body;
  for(const auto& section:document.sections)for(const auto& page:section.pages)for(const auto& block:page.blocks){
    if(block.sheet){body<<"<w:tbl><w:tblPr><w:tblBorders><w:top w:val=\"single\" w:sz=\"4\"/><w:left w:val=\"single\" w:sz=\"4\"/><w:bottom w:val=\"single\" w:sz=\"4\"/><w:right w:val=\"single\" w:sz=\"4\"/><w:insideH w:val=\"single\" w:sz=\"4\"/><w:insideV w:val=\"single\" w:sz=\"4\"/></w:tblBorders></w:tblPr>";for(const auto& [row,cells]:block.sheet->cells){(void)row;body<<"<w:tr>";for(const auto& [column,value]:cells){(void)column;const auto text=value.type==CellType::kNumber?std::to_string(value.number):value.type==CellType::kFormula?"="+value.text:value.text;body<<"<w:tc><w:p><w:r><w:t>"<<strings::xml_escape(text)<<"</w:t></w:r></w:p></w:tc>";}body<<"</w:tr>";}body<<"</w:tbl>";continue;}
    body<<"<w:p><w:pPr>"<<(block.kind==Block::Kind::kHeading?"<w:pStyle w:val=\"Heading1\"/>":"")<<(block.kind==Block::Kind::kListItem?"<w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"1\"/></w:numPr>":"")<<"</w:pPr>";for(const auto& run:block.runs)body<<run_xml(run);body<<"</w:p>";
  }
  ZipArchive zip;zip.add("[Content_Types].xml",content_type("<Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/><Override PartName=\"/word/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml\"/>"));zip.add("_rels/.rels",std::string(relationships)+"<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");
  zip.add("word/document.xml","<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>"+body.str()+"<w:sectPr><w:pgSz w:w=\"11906\" w:h=\"16838\"/></w:sectPr></w:body></w:document>");zip.add("word/_rels/document.xml.rels",std::string(relationships)+"</Relationships>");zip.add("word/styles.xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><w:styles xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:style w:type=\"paragraph\" w:default=\"1\" w:styleId=\"Normal\"><w:name w:val=\"Normal\"/></w:style><w:style w:type=\"paragraph\" w:styleId=\"Heading1\"><w:name w:val=\"heading 1\"/><w:basedOn w:val=\"Normal\"/><w:rPr><w:b/><w:sz w:val=\"32\"/></w:rPr></w:style></w:styles>");zip.write(path,6);
}
void export_xlsx(const Document& document,const std::filesystem::path& path){
  if(document.source_format=="xlsx"&&!document.original_package.empty()){fs::write_bytes_atomic(path,document.original_package);return;}
  std::vector<SheetData> sheets;
  for(const auto& section:document.sections)for(const auto& page:section.pages)for(const auto& block:page.blocks)if(block.sheet)sheets.push_back(*block.sheet);
  if(sheets.empty()){
    SheetData sheet;sheet.name="Sheet1";std::uint32_t row=0;
    for(const auto& line:strings::split_lines(document.plain_text())){CellValue cell;cell.type=CellType::kString;cell.text=line;sheet.cells[row++][0]=std::move(cell);}sheets.push_back(std::move(sheet));
  }
  std::vector<std::string> shared;std::map<std::string,std::size_t> indexes;
  auto shared_index=[&](const std::string& value){auto [item,inserted]=indexes.emplace(value,shared.size());if(inserted)shared.push_back(value);return item->second;};
  std::vector<std::string> sheet_xml;
  for(const auto& model:sheets){
    std::ostringstream xml;xml<<"<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\">";
    if(model.frozen_rows||model.frozen_columns)xml<<"<pane xSplit=\""<<model.frozen_columns<<"\" ySplit=\""<<model.frozen_rows<<"\" state=\"frozen\"/>";
    xml<<"</sheetView></sheetViews><sheetData>";
    for(const auto& [row,cells]:model.cells){xml<<"<row r=\""<<row+1<<"\">";for(const auto& [column,value]:cells){const auto ref=cell_ref(row,column);if(value.type==CellType::kNumber)xml<<"<c r=\""<<ref<<"\"><v>"<<value.number<<"</v></c>";else if(value.type==CellType::kFormula)xml<<"<c r=\""<<ref<<"\"><f>"<<strings::xml_escape(value.text)<<"</f></c>";else if(value.type==CellType::kBoolean)xml<<"<c r=\""<<ref<<"\" t=\"b\"><v>"<<(value.number!=0?1:0)<<"</v></c>";else xml<<"<c r=\""<<ref<<"\" t=\"s\"><v>"<<shared_index(value.text)<<"</v></c>";}xml<<"</row>";}xml<<"</sheetData></worksheet>";sheet_xml.push_back(xml.str());
  }
  std::ostringstream strings_xml;strings_xml<<"<?xml version=\"1.0\" encoding=\"UTF-8\"?><sst xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" count=\""<<shared.size()<<"\" uniqueCount=\""<<shared.size()<<"\">";for(const auto& value:shared)strings_xml<<"<si><t xml:space=\"preserve\">"<<strings::xml_escape(value)<<"</t></si>";strings_xml<<"</sst>";
  std::string overrides="<Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/sharedStrings.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>";
  for(std::size_t index=0;index<sheets.size();++index)overrides+="<Override PartName=\"/xl/worksheets/sheet"+std::to_string(index+1)+".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>";
  ZipArchive zip;zip.add("[Content_Types].xml",content_type(overrides));zip.add("_rels/.rels",std::string(relationships)+"<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
  std::ostringstream workbook,rels;workbook<<"<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>";rels<<relationships;
  for(std::size_t index=0;index<sheets.size();++index){auto name=sheets[index].name.empty()?"Sheet"+std::to_string(index+1):sheets[index].name;workbook<<"<sheet name=\""<<strings::xml_escape(name)<<"\" sheetId=\""<<index+1<<"\" r:id=\"rId"<<index+1<<"\"/>";rels<<"<Relationship Id=\"rId"<<index+1<<"\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet"<<index+1<<".xml\"/>";zip.add("xl/worksheets/sheet"+std::to_string(index+1)+".xml",sheet_xml[index]);}
  workbook<<"</sheets></workbook>";const auto shared_id=sheets.size()+1,styles_id=sheets.size()+2;rels<<"<Relationship Id=\"rId"<<shared_id<<"\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings\" Target=\"sharedStrings.xml\"/><Relationship Id=\"rId"<<styles_id<<"\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>";
  zip.add("xl/workbook.xml",workbook.str());zip.add("xl/_rels/workbook.xml.rels",rels.str());zip.add("xl/sharedStrings.xml",strings_xml.str());zip.add("xl/styles.xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"1\"><font><sz val=\"11\"/><name val=\"Noto Sans\"/></font></fonts><fills count=\"2\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill></fills><borders count=\"1\"><border/></borders><cellStyleXfs count=\"1\"><xf/></cellStyleXfs><cellXfs count=\"1\"><xf xfId=\"0\"/></cellXfs></styleSheet>");zip.write(path,6);
}
